"""Process-local repair memoization and frozen snapshot storage.

The cache holds exactly ``cache_slots`` entries keyed by the semantic identity
of a repair: topology, normalized measured inputs, demands, complete route
contents and the repair settings.  Entries are immutable so a cached repair,
a frozen snapshot and the live inputs can never alias each other.
"""


class RepairCache:
    """Least-recently-repaired bounded cache of immutable repair results."""

    __slots__ = ("slots", "_entries", "_recency")

    def __init__(self, slots):
        self.slots = slots
        self._entries = {}
        self._recency = []

    def lookup(self, key):
        """Return the cached repair for a hit, refreshing its recency."""
        if self.slots <= 0:
            return None
        entry = self._entries.get(key)
        if entry is None:
            return None
        self._touch(key)
        return entry

    def insert(self, key, value):
        """Store a repair, evicting the least recently repaired key when full."""
        if self.slots <= 0:
            return
        if key in self._entries:
            self._entries[key] = value
            self._touch(key)
            return
        self._entries[key] = value
        self._recency.append(key)
        while len(self._recency) > self.slots:
            self._entries.pop(self._recency.pop(0), None)

    def _touch(self, key):
        recency = self._recency
        try:
            recency.remove(key)
        except ValueError:
            pass
        recency.append(key)


