    """Frozen repair publications keyed by caller supplied identifiers."""

    __slots__ = ("_snapshots",)

    def __init__(self):
        self._snapshots = {}

    def freeze(self, identifier, result):
        self._snapshots[identifier] = result

    def get(self, identifier):
        return self._snapshots.get(identifier)
