"""Worst-case shaped request: max topology, 8192 repair-flow budget, max validates."""
import json
import random
import sys
import time

sys.path.insert(0, '/workspace/submission')
sys.path.insert(0, '/workspace/tmp/tests')

from gen import simple_path


def big_topology(rng, nodes=256, links=512, external=16):
    ids = rng.sample(range(0, 65536), nodes)
    names = ['N%02d' % i if i < 100 else 'M%03d' % i for i in range(nodes)]
    node_list = [{"id": ids[i], "name": names[i], "external_capacity": rng.randint(10 ** 6, 10 ** 9)}
                 for i in range(nodes)]
    adjacency = {ids[i]: [] for i in range(nodes)}
    link_list = []
    degree = {i: 0 for i in ids}
    # a connected ring plus random extras to reach the link count
    for k in range(nodes):
        a, b = ids[k], ids[(k + 1) % nodes]
        link_list.append({"source": a, "target": b, "capacity": rng.randint(10 ** 6, 10 ** 9)})
        adjacency[a].append(b)
        adjacency[b].append(a)
        degree[a] += 1
        degree[b] += 1
    seen = {(min(l["source"], l["target"]), max(l["source"], l["target"])) for l in link_list}
    guard = 0
    while len(link_list) < links and guard < 200000:
        guard += 1
        a, b = rng.sample(ids, 2)
        if degree[a] >= 8 or degree[b] >= 8:
            continue
        key = (min(a, b), max(a, b))
        if key in seen:
            continue
        seen.add(key)
        degree[a] += 1
        degree[b] += 1
        link_list.append({"source": a, "target": b, "capacity": rng.randint(10 ** 6, 10 ** 9)})
    external_names = names[:external]
    return {"nodes": node_list, "links": link_list, "external_nodes": external_names}


def big_plan(rng, topology):
    names = topology["external_nodes"]
    id_name = {node["id"]: node["name"] for node in topology["nodes"]}
    id_of = {node["name"]: node["id"] for node in topology["nodes"]}
    adjacency = {}
    for node in topology["nodes"]:
        adjacency[node["id"]] = []
    for link in topology["links"]:
        adjacency[link["source"]].append(link["target"])
        adjacency[link["target"]].append(link["source"])
    plan = {}
    hops = 0
    for source in names:
        bundle = {}
        for target in names:
            if source == target:
                continue
            entries = []
            weight = 1000
            for index in range(rng.randint(1, 4)):
                if index == 3:
                    share = weight
                else:
                    share = rng.randint(1, max(1, weight - (3 - index)))
                weight -= share
                path = simple_path(rng, adjacency, id_of[source], id_of[target], max_vertices=9)
                if path is None or hops + len(path) > 4050:
                    if not entries:
                        break
                    continue
                hops += len(path)
                entries.append({"path": [id_name[i] for i in path], "weight": share})
            if not entries:
                raise SystemExit('no path for %s->%s' % (source, target))
            total = sum(e["weight"] for e in entries)
            entries[0]["weight"] += 1000 - total
            bundle[target] = entries
        plan[source] = bundle
    return plan


def build(seed=5, streams=2, repair_events=4, validate_events=8, demand_scale=10 ** 9):
    rng = random.Random(seed)
    request = {"streams": []}
    for _ in range(streams):
        topology = big_topology(rng)
        plan = big_plan(rng, topology)
        settings = {"trials": 32, "epsilon": 250000, "seed": rng.randint(0, 2 ** 32 - 1),
                    "cutoff": [1, 4], "bias": 24000, "tau": 30000, "gamma": [4, 5],
                    "cache_slots": 1}
        external_ids = {node["id"] for node in topology["nodes"]
                        if node["name"] in topology["external_nodes"]}
        pairs = [(a, b) for a in external_ids for b in external_ids if a != b]
        demands = {pair: rng.randint(0, demand_scale) for pair in pairs}
        counters = {}
        for link in topology["links"]:
            name = {node["id"]: node["name"] for node in topology["nodes"]}
            counters["low_%s_egress_to_%s" % (name[link["source"]], name[link["target"]])] = {
                "perturbed": rng.randint(0, link["capacity"])}
        events = [{"op": "patch",
                   "demands": [[pair[0], pair[1], value] for pair, value in demands.items()],
                   "counters": counters},
                  {"op": "routes", "label": "base", "paths": plan}]
        for index in range(repair_events):
            if index:
                key = sorted(counters)[index % len(counters)]
                events.append({"op": "patch", "demands": [],
                               "counters": {key: {"perturbed": rng.randint(0, 10 ** 9)}}})
            events.append({"op": "repair", "id": "snap%d" % index})
        for index in range(validate_events):
            if index % 2:
                events.append({"op": "validate", "id": "snap%d" % (index % repair_events)})
            else:
                events.append({"op": "patch", "demands":
                               [[pair[0], pair[1], rng.randint(0, demand_scale)]
                                for pair in pairs[:40]]})
                events.append({"op": "validate", "id": "snap%d" % (index % repair_events)})
        request["streams"].append({"topology": topology, "settings": settings, "events": events})
    return request


def main():
    request = build()
    data = json.dumps(request, separators=(',', ':')).encode()
    print('request bytes', len(data))
    flows = 0
    for stream in request["streams"]:
        topology = stream["topology"]
        flows += 2 * len(topology["links"]) + 2 * len(topology["external_nodes"])
    validate_cost = 0
    for stream in request["streams"]:
        cost = 4 * len(stream["topology"]["links"]) + 2 * len(stream["topology"]["external_nodes"])
        validate_cost += cost * sum(1 for e in stream["events"] if e["op"] == "validate")
    print('repair flow total', flows, 'validate cell total', validate_cost)
    from crosscheck import run_request
    start = time.monotonic()
    answer = run_request(request)
    elapsed = time.monotonic() - start
    print('elapsed %.2fs' % elapsed)
    hits = sum(1 for stream in answer["streams"] for e in stream["events"]
               if e.get("op") == "repair" and e["cache_hit"])
    repairs = sum(1 for stream in answer["streams"] for e in stream["events"] if e.get("op") == "repair")
    print('repairs', repairs, 'hits', hits)
    return 0 if elapsed < 110 else 1


if __name__ == '__main__':
    sys.exit(main())
